/* A county that remembers: camp, neighbors, newspapers, seasons and legacy. */
(()=>{'use strict';
const Q=(title,prompt,choices,answer,hint)=>({kind:'choice',title,prompt,choices,answer,hint});
const O=(title,prompt,choices,answer,hint)=>({kind:'sequence',title,prompt,choices,answer,hint});
const puzzles={
 tent:O('Pitch your woodland tent','The camp card says choose level ground, lay the groundsheet, raise the tent, then secure its lines.',['Raise tent','Secure lines','Choose level ground','Lay groundsheet'],[2,3,0,1],'Start with a good place to sleep.'),
 fire:O('Tend the bonfire','Prepare the stone ring, arrange dry tinder and kindling, then build a steady flame.',['Build steady flame','Prepare stone ring','Arrange tinder and kindling'],[1,2,0],'Give the shared fire a proper hearth before lighting it.'),
 stew:O('Woodland campfire stew','The recipe says prepare the vegetables, add broth, then simmer the pot over gentle heat.',['Simmer gently','Prepare vegetables','Add broth'],[1,2,0],'The ingredients go into the pot before the slow simmer.'),
 toast:Q('A golden toasted treat','Where does a marshmallow toast evenly?',['Inside the fiercest flame','Turned gently above glowing embers','Buried in cold ash'],1,'Gentle heat gives the outside time to turn golden.'),
 stars:O('The Campfire Crown constellation','Willow points out Star → Pine → Moon → Star. Trace the chart.',['Moon','Star','Pine'],[1,2,0,1],'The constellation returns to its first star.'),
 song:O('The bonfire refrain','The circle sings Ember → River → Star → Ember. Repeat its refrain.',['Star','Ember','River'],[1,2,0,1],'The song begins and ends beside the fire.'),
 tale:Q('Make room in the story circle','A listener wants a gentle tale tonight. What do you offer?',['Let them choose a story and a comfortable place','Insist on the loudest ghost story','Send them away'],0,'A good gathering listens as well as tells.'),
 provisions:Q('Fern’s bakery provisions','The first bake needs flour, water and yeast. Which order fits?',['Flour, water and yeast','Only flowers and candles','Only salt'],0,'Choose what will become bread.'),
 oven:Q('Bring the old oven back','The door hinge is loose, but its stone hearth is sound. What should be repaired?',['The sound stone hearth','The loose hinge, keeping the good stonework','Every part whether damaged or not'],1,'Repair what needs care and preserve what is sound.'),
 loaf:O('Fern’s first bakery loaves','Mix, knead, prove, then bake. Put the first batch in order.',['Bake','Mix','Prove','Knead'],[1,3,2,0],'Give the shaped dough time to rise.'),
 musicpage:Q('A melody in the archive','Aurelia’s old page has a missing phrase. What will help recover it?',['Compare the surviving notes with the festival refrain','Throw away the surviving page','Guess without listening'],0,'What remains can help recover what was lost.'),
 harmony:O('Aurelia’s remembered harmony','The recovered phrase is Moon → Leaf → Star → Moon.',['Star','Moon','Leaf'],[2,1,0,2],'The song circles back to Moon.'),
 flowers:Q('Flowers for Pip’s gathering','How can you gather flowers while leaving the garden alive?',['Take a small share and leave plenty blooming','Pull out all the roots','Take every bloom'],0,'A welcome should leave room for tomorrow.'),
 welcome:Q('A celebration everyone can enjoy','One guest needs quiet and another loves music. What should the gathering offer?',['A music circle and a quieter place nearby','Only the loudest spot','No choices'],0,'Different people can belong at the same gathering.'),
 seed:O('Spring planting circle','Prepare soil, plant the seed, water gently, then mark the bed.',['Water gently','Mark bed','Prepare soil','Plant seed'],[2,3,0,1],'The roots need a home first.'),
 fireflies:Q('Summer firefly gathering','What makes a good firefly walk?',['Quiet observation with gentle lantern light','Chasing and trapping every light','Bright floodlights'],0,'Leave the woodland lights free to move.'),
 harvest:Q('Autumn harvest supper','There are twelve guests and each tray serves four. How many trays?',['Two','Three','Five'],1,'Divide twelve by four.'),
 winter:Q('Winter storytelling night','What welcomes a traveler into the winter circle?',['Warm blankets, a hot drink and a place beside the fire','An empty cold bench','A demand for a gift before entry'],0,'Warmth and a welcome belong together.'),
 trade:Q('The midnight market’s gift','A stall offers a moonlit recipe in return for a remembered kindness. What do you offer?',['A true account of helping a neighbor','A demand for all the stall’s treasures','Nothing but an insult'],0,'The hidden market trades in care as well as things.'),
 moonflower:Q('The hidden moonflower path','A silver bloom stands beside a growing bud. What do you collect?',['One fallen petal and leave the living plants','Both plants by the roots','Every flower in the garden'],0,'The garden gives a keepsake without losing its future.')
};
const ST=(district,room,puzzle,text)=>({district,room,puzzle,text});
const stories=[
{id:'fernBakery',person:'Fern',title:'The Bakery with Its Lights Out',reward:55,steps:[ST('market','merchant','provisions','Gather the bakery’s first provisions.'),ST('workshop','craft','oven','Repair the old oven door.'),ST('capital','countyBakery','loaf','Bake the first loaves in Fern’s reopened bakery.')],outcome:'Fern’s Hearth Bakery is open again. Its first warm loaves welcome the county.',letter:'You helped turn a dark window into a warm welcome. There will always be a loaf waiting for a friend.'},
{id:'aureliaSong',person:'Aurelia',title:'The Song She Thought She Had Lost',reward:50,steps:[ST('library','memoryHall','musicpage','Find the surviving page of Aurelia’s melody.'),ST('academy','runes','harmony','Recover the missing musical phrase.'),ST('forest','countyCamp','song','Help Aurelia sing again beside the bonfire.')],outcome:'Aurelia’s recovered song joins the bonfire festival. The circle has a new refrain.',letter:'I thought the song was gone. You helped me hear it again. Meet me where the lanterns hang above the campfire.'},
{id:'pipGathering',person:'Pip',title:'A Celebration Big Enough for Everyone',reward:45,steps:[ST('gardens','garden','flowers','Gather flowers for Pip’s family celebration.'),ST('home','home','welcome','Plan a gathering with music and a quiet corner.'),ST('forest','countyCamp','tale','Welcome the family to the bonfire story circle.')],outcome:'Pip’s family celebration fills the campground with music, quiet conversations and a place for everyone.',letter:'You made room for every one of us. I kept a little ribbon from the evening for your legacy room.'}
];
const seasons={spring:{title:'The Spring Seed Gathering',district:'gardens',room:'garden',puzzle:'seed',keepsake:'Spring seed ribbon',text:'Plant together, trade growing hopes, and welcome a new season.'},summer:{title:'The Summer Firefly Camp',district:'forest',room:'countyCamp',puzzle:'fireflies',keepsake:'Firefly lantern keepsake',text:'Follow the woodland lights and gather around the bonfire.'},autumn:{title:'The Autumn Harvest Bonfire',district:'forest',room:'countyCamp',puzzle:'harvest',keepsake:'Harvest supper bowl',text:'Share the harvest at long tables beside the fire.'},winter:{title:'The Winter Fireside Stories',district:'forest',room:'owlTreehouse',puzzle:'winter',keepsake:'Winter story quilt square',text:'Blankets, warm drinks and tales beneath Aurelin’s branches.'}};
const campActivities=[{id:'festival',title:'Host the Embermere Bonfire Festival',puzzle:'welcome',fire:true,prize:'Embermere bonfire festival pennant'},{id:'tent',title:'Pitch my canvas tent',puzzle:'tent',prize:'My first camp pennant'},{id:'fire',title:'Tend the shared bonfire',puzzle:'fire',prize:'Bonfire keeper’s ember stone'},{id:'stew',title:'Cook woodland stew',puzzle:'stew',fire:true,prize:'Woodland camp recipe'},{id:'toast',title:'Toast a golden treat',puzzle:'toast',fire:true,prize:'Toasted-sweet keepsake'},{id:'stars',title:'Stargaze & trace the sky',puzzle:'stars',prize:'Campfire Crown star chart'},{id:'song',title:'Sing around the bonfire',puzzle:'song',prize:'Bonfire song ribbon'},{id:'tale',title:'Host a fireside story circle',puzzle:'tale',prize:'The story-circle lantern'}];
function record(x){return x&&typeof x==='object'&&!Array.isArray(x)}
function ensure(s){if(!record(s.cityCounty))s.cityCounty={};const q=s.cityCounty;for(const k of ['seen','stories','campDays','celebrated','hidden','photos','reactions','displays'])if(!record(q[k]))q[k]={};for(const k of ['events','pending','letters','campKeepsakes'])if(!Array.isArray(q[k]))q[k]=[];if(!Number.isSafeInteger(q.lastPromise)||q.lastPromise<0)q.lastPromise=0;return q}
function event(s,key,title,text,kind,c){const q=ensure(s);if(q.events.some(e=>e.key===key))return; q.events.unshift({key,title,text,kind,day:c.key});q.events=q.events.slice(0,100)}
function letter(s,key,person,title,text,c){const q=ensure(s);if(q.letters.some(l=>l.key===key))return;q.letters.unshift({key,person,title,text,day:c.key});q.letters=q.letters.slice(0,60)}
function snapshot(s){return{crafted:s.crafted||0,quest:s.cityLife?.questSteps||0,stories:Object.values(s.cityCounty?.stories||{}).filter(x=>x.complete).length,home:Object.values(s.cityLife?.upgrades||{}).filter(Boolean).length,heritage:Object.values(s.cityHeritage?.completed||{}).filter(Boolean).length}}
function observe(s,c){const q=ensure(s),now=snapshot(s);if(!q.initialized){q.seen=now;q.lastPromise=s.cityPromise?.serial||0;q.initialized=true;return}for(const [key,n]of Object.entries(now)){if(n>(q.seen[key]||0)&&key==='crafted')event(s,'craft:'+n,'Good work at the county’s benches',n+' pairs have now been completed by Eldoria’s visiting maker.','work',c);q.seen[key]=n}const fresh=(s.cityPromise?.items||[]).filter(item=>item.id>q.lastPromise);for(const item of fresh){if(!q.pending.some(p=>p.source===item.id)){q.pending.push({source:item.id,kind:item.kind,title:item.title,night:item.night});q.pending=q.pending.slice(-100)}}q.lastPromise=s.cityPromise?.serial||0}
function ordinal(key){const n=Date.parse(key+'T00:00:00Z');return Number.isFinite(n)?n/86400000+1:0}
const reactions={cook:['Fern','The aroma of your midnight cooking reached the tavern. Shall we share a supper?'],craft:['Master Cobble','The couriers are talking about your workmanship. I saved you a place at the bench.'],home:['Pip','Your cottage has a new warmth. I would love to come by and see what you made.'],garden:['Keeper Willow','The garden carries a rare midnight glow. You left something beautiful growing here.'],magic:['Professor Thistle','Your spell has found its clear note. There is more to learn whenever you are ready.'],friend:['Pip','A little kindness changed the morning. We remembered.'],friendship:['Pip','We are still smiling about your midnight kindness.'],quest:['Fern','The people you helped have been talking about it all morning.'],goals:['Fern','You left the neighborhood better than you found it.'],answers:['Archivist Rowan','The records seem clearer this morning. Your answer belongs in the family’s account.'],story:['Archivist Rowan','A new thread in the family’s story has come into the light.']};
function morning(s,c){const q=ensure(s);let changed=false;for(const p of q.pending){if(p.done||ordinal(p.night)>c.ordinal||(ordinal(p.night)===c.ordinal&&c.hour<6))continue;p.done=true;changed=true;const r=reactions[p.kind]||['Aurelia','Last night’s wonder is part of the county’s story now.'];event(s,'morning:'+p.source,'Morning remembers: '+p.title,r[0]+' says: “'+r[1]+'”','morning',c);letter(s,'midnight:'+p.source,r[0],'About last night’s wonder',r[1],c)}q.pending=q.pending.filter(p=>!p.done);if(q.sleep&&(c.ordinal>q.sleep.dawn||(c.ordinal===q.sleep.dawn&&c.hour>=6))&&!q.sleep.woke){q.sleep.woke=true;changed=true;s.life??={};s.life.bag??={};s.life.bag['woodland breakfast']=(s.life.bag['woodland breakfast']||0)+1;if(!q.campKeepsakes.includes('A dew-bright camping morning'))q.campKeepsakes.push('A dew-bright camping morning');event(s,'camp-wake:'+q.sleep.key,'A morning beneath the pines','Your tent held its place through the night. A woodland breakfast and a dew-bright camp memory are waiting.','camp',c);letter(s,'camp-wake:'+q.sleep.key,'Willow','Good morning, camper','The lake is bright, the kettle is warm, and your place beside the fire is still here.',c)}return changed}
function at(st,w){return !!st&&!!w&&st.district===w.district&&st.room===w.room&&!w.porch}
function check(s,id,response){const p=puzzles[id];const value=globalThis.EldoriaPromiseModel?.guide(s,p,response)??response;return p.kind==='sequence'?Array.isArray(value)&&value.length===p.answer.length&&value.every((v,i)=>v===p.answer[i]):value===p.answer}
function keepsake(s,text){const q=ensure(s);if(!q.campKeepsakes.includes(text))q.campKeepsakes.push(text)}
function camp(s,id,response,w,c){const q=ensure(s),a=campActivities.find(a=>a.id===id);if(!a||!at({district:'forest',room:'countyCamp'},w))return{ok:false,reason:'Visit Embermere Campground first.'};const key=c.key;if(!q.campDays[key])q.campDays[key]={};const day=q.campDays[key];if(a.fire&&!day.fire&&!globalThis.EldoriaPromiseModel?.active(s))return{ok:false,reason:'Tend the bonfire before cooking over its embers.'};if(id==='festival'&&!globalThis.EldoriaPromiseModel?.active(s)&&(!day.fire||!day.stew||(!day.song&&!day.tale)))return{ok:false,reason:'Prepare the bonfire, cook a woodland stew, and share a song or story before hosting the festival.'};if(!check(s,a.puzzle,response))return{ok:false,reason:puzzles[a.puzzle].hint};const first=!day[id];day[id]=true;if(id==='tent')q.tent=true;if(a.fire)day.fire=true;if(first){keepsake(s,a.prize);if(id==='festival')letter(s,'bonfire:'+key,'Willow','Your Embermere bonfire festival','The food, the songs, and the welcome made this a night to remember. Your place in the circle is always here.',c);if(['stew','toast'].includes(id)){s.cookedMeals=(s.cookedMeals||0)+1;s.life??={};s.life.bag??={};s.life.bag[id==='stew'?'woodland stew':'golden toasted treat']=(s.life.bag[id==='stew'?'woodland stew':'golden toasted treat']||0)+1}event(s,'camp:'+key+':'+id,a.title+' at Embermere','A little camping memory joins your county story.','camp',c)}return{ok:true,title:a.title+' · '+(first?'a memory made':'enjoyed again'),first}}
function settle(s,w,c){const q=ensure(s);if(!at({district:'forest',room:'countyCamp'},w)||!q.tent)return{ok:false,reason:'Pitch your tent at Embermere before settling in.'};const dawn=c.ordinal+(c.hour>=6?1:0);if(q.sleep?.dawn===dawn)return{ok:false,reason:'Your overnight camp is already saved. The real clock will bring the morning.'};q.sleep={key:c.key,dawn,woke:false};return{ok:true,title:'Your tent is ready for the night'}}
function eat(s,food,share,w,c){const allowed=['woodland stew','golden toasted treat','woodland breakfast','woodland loaf'];if(!allowed.includes(food)||!at({district:'forest',room:'countyCamp'},w)||!(s.life?.bag?.[food]>0))return{ok:false,reason:'Bring a prepared camping meal to the bonfire circle.'};s.life.bag[food]--;s.mealsEnjoyed=(s.mealsEnjoyed||0)+1;if(share&&s.cityLife)s.cityLife.friends.willow=(s.cityLife.friends.willow||0)+1;event(s,'meal:'+food+':'+c.key+(share?':shared':''),share?'A supper shared beside the bonfire':'A good meal beside the bonfire',share?'Willow and the circle remember your warm welcome.':'A little time, a warm plate, and a place beside the fire.','camp',c);return{ok:true,title:share?'Your campfire supper is shared':'Your woodland meal is enjoyed'}}
function storyInfo(s,id){const st=stories.find(st=>st.id===id);if(!st)return null;const q=ensure(s);if(!q.stories[id])q.stories[id]={step:0,complete:false};return{story:st,progress:q.stories[id],step:st.steps[q.stories[id].step]}}
function answerStory(s,id,response,w,c){const i=storyInfo(s,id);if(!i||i.progress.complete||!at(i.step,w))return{ok:false,reason:'Follow this resident’s current story location.'};if(!check(s,i.step.puzzle,response))return{ok:false,reason:puzzles[i.step.puzzle].hint};i.progress.step++;if(i.progress.step<i.story.steps.length)return{ok:true,next:true};i.progress.complete=true;s.coins+=i.story.reward;event(s,'resident:'+id,i.story.title+' · a new beginning',i.story.outcome,'resident',c);letter(s,'resident:'+id,i.story.person,'A letter from '+i.story.person,i.story.letter,c);keepsake(s,id==='fernBakery'?'Fern’s first-bake apron ribbon':id==='aureliaSong'?'Aurelia’s recovered music page':'Pip’s family celebration ribbon');return{ok:true,title:i.story.outcome,coins:i.story.reward}}
function celebrate(s,response,w,c){const a=seasons[c.season],q=ensure(s),key=c.year+':'+c.season;if(!at(a,w))return{ok:false,reason:'Visit the seasonal gathering’s location.'};if(!check(s,a.puzzle,response))return{ok:false,reason:puzzles[a.puzzle].hint};const first=!q.celebrated[key];q.celebrated[key]=true;if(first){keepsake(s,a.keepsake);s.coins+=20;event(s,'season:'+key,a.title+' brings neighbors together',a.text,'season',c)}return{ok:true,title:a.title+' · '+(first?'a season remembered':'welcome back'),coins:first?20:0}}
function hidden(s,id,response,w,c){const a=id==='market'?{district:'market',room:'midnightMarket',puzzle:'trade',prize:'The midnight market’s moonlit recipe'}:{district:'gardens',room:'moonGarden',puzzle:'moonflower',prize:'A petal from the hidden moonflower garden'};if(!globalThis.EldoriaPromiseModel?.active(s,c)||!at(a,w))return{ok:false,reason:'This path is revealed only during the Midnight Promise.'};if(!check(s,a.puzzle,response))return{ok:false,reason:puzzles[a.puzzle].hint};const q=ensure(s),key=c.key+':'+id;if(q.hidden[key])return{ok:false,reason:'Tonight’s keepsake is already yours. Enjoy the hidden place or return at another midnight.'};q.hidden[key]=true;keepsake(s,a.prize);event(s,'hidden:'+key,'A midnight place remembered',a.prize+' was found beneath the county’s enchantment.','hidden',c);return{ok:true,title:a.prize}}
function photo(s,id,title,image,c){const q=ensure(s);if(!q.photos[id])q.photos[id]={title,image,day:c.key};return{ok:true,title:'A photograph saved for your legacy room'}}
function legacyItems(s){const q=ensure(s),items=[];for(const [id,p]of Object.entries(q.photos))items.push({id:'photo:'+id,title:p.title,text:'Photographed on '+p.day,image:p.image,type:'photo'});for(const l of q.letters)items.push({id:'letter:'+l.key,title:l.title,text:l.text,image:'',type:'letter'});for(const name of [...new Set([...(s.cityLife?.collection||[]),...q.campKeepsakes])])items.push({id:'keepsake:'+name,title:name,text:'A keepsake from your life in Eldoria.',image:'',type:'keepsake'});for(const p of(s.cityPromise?.items||[]).slice(0,30))items.push({id:'promise:'+p.id,title:p.title,text:p.purpose||'Perfect work remembered from '+p.night,image:'',type:'creation'});return items}
function display(s,id){const q=ensure(s);if(!legacyItems(s).some(item=>item.id===id))return{ok:false,reason:'Earn or photograph this memory before displaying it.'};if(q.displays[id]){delete q.displays[id];return{ok:true}}if(Object.keys(q.displays).length>=8)return{ok:false,reason:'Choose eight treasured memories. Put one away to make room.'};q.displays[id]=true;return{ok:true}}
function respond(s,eventKey,c){const q=ensure(s),e=q.events.find(e=>e.key===eventKey);if(!e||e.kind!=='morning'||q.reactions[eventKey])return{ok:false,reason:'This morning moment has already been shared.'};q.reactions[eventKey]=true;const person=e.text.split(' says:')[0],map={'Fern':'fern','Master Cobble':'cobble','Pip':'pip','Keeper Willow':'willow','Professor Thistle':'thistle','Aurelia':'aurelia'};if(map[person]&&s.cityLife)s.cityLife.friends[map[person]]=(s.cityLife.friends[map[person]]||0)+1;return{ok:true,title:'A morning moment shared with '+person}}
globalThis.EldoriaCountyModel={puzzles,stories,seasons,campActivities,ensure,event,letter,observe,morning,at,check,camp,settle,eat,storyInfo,answerStory,celebrate,hidden,photo,legacyItems,display,respond};
})();
